package net.officefloor.hq.app.person;


/** Give each selected person the grade from the from-date (the sheet's today when none was given), in list order
 *  (the order they were added), exactly as the person form's edit would: a new version, the grade recorded from
 *  the date keeping those from other dates, name and terms kept, its PERSON_EDITED line and then how the sheet's
 *  figures moved over it. A selected id not on the sheet is skipped. A viewer's bulk grade changes nobody and writes
 *  nothing. */
public class BulkGradePeople {
    public void grade(@PathVariable("sheetId") String sheetId, @Val BulkGradeInput input, PersonRepository people,
            SheetRepository sheets, RoleRepository roles, Rollups rollups, Audit audit, Out<BulkGradeResponse> result) {
        String sheet = sheetId.trim();
        if (Role.VIEWER.equals(roles.of(sheet, input.user()))) {
            result.set(new BulkGradeResponse(0));
            return;
        }
        LocalDate from = input.from() != null ? input.from() : sheets.today(sheet);
        int changed = 0;
        for (Person loaded : people.list(sheet)) {
            if (!input.personIds().contains(loaded.id())) {
                continue;
            }
            Rollup before = rollups.take(sheet);
            Person person = new Person(loaded.id(), loaded.sheetId(), loaded.name(), loaded.grade(),
                    loaded.version() + 1, loaded.statementCount(), loaded.statedTotal(), loaded.statementDate(),
                    loaded.retiredFrom(), loaded.grades(), loaded.holds(), loaded.terms());
            if (!people.update(person, loaded.version())) {
                continue;
            }
            people.grade(person, input.grade(), from);
            PersonResponse saved = PersonResponse.from(people.find(sheet, loaded.id()));
            audit.record("PERSON_EDITED sheet=" + sheet + " by=" + input.user()
                    + " name=" + saved.name() + " grade=" + saved.grade());
            rollups.record(sheet, input.user(), before);
            changed++;
        }
        result.set(new BulkGradeResponse(changed));
    }
}
package net.officefloor.hq.app.person;


/** Bind the body and refuse it before anything is read: a signed-in user, at least one selected person, a grade of
 *  A, B or C, and a from-date (optional) that is a real yyyy-mm-dd date. */
public class ValidateBulkGrade {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody BulkGradeRequest request, Out<BulkGradeInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        if (request.personIds() == null || request.personIds().isEmpty()) {
            throw new InvalidPersonException("Select the people to grade.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String from = request.from() == null ? "" : request.from().trim();
        LocalDate fromDate = null;
        if (!from.isEmpty()) {
            try {
                fromDate = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date, yyyy-mm-dd.");
            }
        }
        body.set(new BulkGradeInput(request.user().trim(), new LinkedHashSet<>(request.personIds()), grade, fromDate));
    }
}
package net.officefloor.hq.app.claim;


/** The terms a new claim is fixed with when it is created, and the due-by they give; a claim belongs to the period
 *  holding its due-by. */
public final class DueBy {

    private DueBy() {
    }

    /** The terms (business days) a new claim of the person dated on the date is fixed with: the person's own terms,
     *  else the terms of their grade in force on the date (else the sheet's terms in force on it). */
    public static int terms(Person person, LocalDate date, SettingRepository settings) {
        return person.terms() != null ? person.terms()
                : settings.termsFor(person.sheetId(), person.grades().on(date), date);
    }

    /** The due-by of a new claim of the person dated on the date: the terms-th business day after the date, skipping
     *  Saturdays, Sundays and the sheet's holidays as they are now. */
    public static LocalDate of(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
        return holidays.dueBy(person.sheetId(), date, terms(person, date, settings));
    }
}

